set -x; uv run --no-project --python 3.13 python - <<'PY'
import re, sys, pathlib
B = pathlib.Path("ios/BooksAndVocab")
files = sorted(B.rglob("*.swift"))
if len(files) < 400:
    print("FAIL scan-floor: %d swift files under %s" % (len(files), B)); sys.exit(1)
code = {p: "\n".join(l for l in p.read_text(encoding="utf-8", errors="ignore").splitlines()
                    if not l.lstrip().startswith(("//", "*", "/*"))) for p in files}
flat = {p: re.sub(r"\s+", " ", code[p]) for p in files}
READER, SETTINGS = B / "Views/Reader", B / "Views/Settings"
ANCHORS = ("Views/Settings/SettingsReviewSection.swift",
           "Views/Vocabulary/Scenes/ReviewCardLayoutEditor.swift",
           "Views/Reader/ReaderSettingsPresenter+Vocab.swift")
for rel in ANCHORS:
    if (B / rel) not in code:
        print("FAIL anchor file missing: %s (renamed? re-derive this criterion)" % (B / rel)); sys.exit(1)
def tree(d): return [p for p in files if d in p.parents]
if not tree(READER) or not tree(SETTINGS):
    print("FAIL scan-floor: Views/Reader or Views/Settings is empty"); sys.exit(1)
ok = True

STRUCTS = set()
for p in files:
    STRUCTS |= set(re.findall(r'^\s*(?:public |internal |fileprivate |private |final )*struct ([A-Za-z0-9_]+)', code[p], re.M))
SEL = re.compile(r'\b([A-Z][A-Za-z0-9_]*)\s*\(\s*isSelected\s*:')
def sel_types(d):
    out = {}
    for p in tree(d):
        for n in set(SEL.findall(flat[p])) & STRUCTS:
            out.setdefault(n, []).append(str(p))
    return out
r_sel, s_sel = sel_types(READER), sel_types(SETTINGS)
print("G1 reader selection types: %s" % sorted(r_sel))
print("G1 settings selection types: %s" % sorted(s_sel))
extra = sorted(set(r_sel) - set(s_sel))
if extra:
    print("FAIL G1: Views/Reader instantiates selection type(s) Views/Settings never uses: %s" % extra)
    for n in extra: print("        %s used at %s" % (n, r_sel[n]))
    ok = False
elif not r_sel and s_sel:
    print("FAIL G1: Views/Settings still has selection tiles (%s) but Views/Reader shares none" % sorted(s_sel)); ok = False
else:
    print("G1 OK: reader shares %s with settings" % sorted(r_sel))

PAIR = re.compile(r'isSelected\s*\?\s*[\w.]*\bpalette\.\w+\s*:\s*[\w.]*\bpalette\.\w+')
PROP = re.compile(r'^\s*(?:public |internal |fileprivate |private )*let isSelected\s*:\s*Bool\b', re.M)
own = []
for p in tree(READER):
    own += ["%s :: %s" % (p, m.group(0)) for m in PAIR.finditer(flat[p])]
    own += ["%s :: let isSelected: Bool" % p for _ in PROP.findall(code[p])]
print("G2 hand-rolled selection chrome under Views/Reader: %d" % len(own))
for h in own[:8]: print("        %s" % h)
if own:
    print("FAIL G2: Views/Reader still owns selection-tile chrome of its own"); ok = False

NARROW = re.compile(r'isSelected\s*\?\s*[\w.]*\bpalette\.mutedFill\s*:\s*[\w.]*\bpalette\.pageBackground')
hits = [str(p) for p in files for _ in NARROW.finditer(flat[p])]
print("G3 selected-fill sites: %s" % hits)
if len(hits) > 1:
    print("FAIL G3: the selected/unselected fill pair is written in %d places" % len(hits)); ok = False

SYM = re.compile(r'\b([A-Za-z_][A-Za-z0-9_]*)\s*\(')
declared = set(STRUCTS)
for p in files:
    declared |= set(re.findall(r'^\s*(?:public |internal |fileprivate |private |static )*func ([a-zA-Z0-9_]+)\s*\(', code[p], re.M))
def used(rel):
    return set(SYM.findall(code[B / rel])) & declared
freq = {}
def rare(s):
    if s not in freq:
        pat = re.compile(r'\b%s\s*\(' % re.escape(s))
        freq[s] = sum(1 for p in files if pat.search(code[p]))
    return freq[s] <= 20
READER_SETTINGS = "Views/Reader/ReaderSettingsPresenter+Vocab.swift"
vocab = sorted(s for s in (used("Views/Settings/SettingsReviewSection.swift")
                           & used("Views/Vocabulary/Scenes/ReviewCardLayoutEditor.swift")) if rare(s))
print("G4 converged vocabulary: %s" % vocab)
if len(vocab) < 2:
    print("FAIL G4: vocabulary has %d members; the two reference pages no longer agree" % len(vocab)); ok = False
else:
    shared = sorted(used(READER_SETTINGS) & set(vocab))
    print("G4 reader settings adopts: %s" % shared)
    if len(shared) < 2:
        print("FAIL G4: reader settings shares %d of that vocabulary, need >= 2" % len(shared)); ok = False

OLD = re.compile(r'AppSectionBlock\s*\([^)]*flat\s*:\s*true')
old = [str(p) for p in files for _ in OLD.finditer(flat[p])]
old += ["%s :: AppAirDivider" % READER_SETTINGS for _ in re.finditer(r'\bAppAirDivider\s*\(', flat[B / READER_SETTINGS])]
print("G5 retired grouping model still in use: %s" % old)
if old:
    print("FAIL G5: reader settings still groups with AppSectionBlock(flat:true) / AppAirDivider"); ok = False

print("RESULT %s" % ("PASS" if ok else "FAIL"))
sys.exit(0 if ok else 1)
PY
